     1	import java.util.List;
     2	
     3	/**
     4	 * The item types the MHPCO insures at all: the main items of its price list
     5	 * and the components it offers. An item of any other type cannot be covered,
     6	 * and the MHPCO declines the whole request rather than quoting around it.
     7	 */
     8	public final class InsurableItems {
     9	
    10	    private InsurableItems() {
    11	    }
    12	
    13	    public static boolean isInsurable(String itemType) {
    14	        return MainItemPricing.isMainItem(itemType) || ComponentPricing.isComponent(itemType);
    15	    }
    16	
    17	    /**
    18	     * What the MHPCO insures one item for. Each family of insurable item is
    19	     * valued by the pricing policy that owns it: a main item by the price
    20	     * list, a component by the flat component value. This is the one place
    21	     * the MHPCO's partition of insurable items into families is applied to a
    22	     * valuation, alongside the one place that decides whether an item is
    23	     * insurable at all.
    24	     */
    25	    public static int insuranceValueOf(Item item) {
    26	        if (ComponentPricing.isComponent(item.type())) {
    27	            return ComponentPricing.componentInsuranceValue(item);
    28	        }
    29	        return MainItemPricing.mainItemInsuranceValue(item);
    30	    }
    31	
    32	    public static void requireAllInsurable(List<Item> items) {
    33	        items.stream()
    34	                .map(Item::type)
    35	                .filter(itemType -> !isInsurable(itemType))
    36	                .findFirst()
    37	                .ifPresent(itemType -> {
    38	                    throw new IllegalArgumentException(
    39	                            "The MHPCO does not insure items of type " + itemType);
    40	                });
    41	    }
    42	}
