     1	import java.math.BigDecimal;
     2	import java.util.List;
     3	import java.util.function.Predicate;
     4	
     5	/**
     6	 * The MHPCO's item-specific risk surcharges. A surcharge is charged only for
     7	 * the items that carry the risk, and is measured against that item's own base
     8	 * premium -- never against the policy total.
     9	 */
    10	public final class ItemRiskSurcharges {
    11	
    12	    private static final int CURSE_SURCHARGE_PERCENT = 50;
    13	
    14	    private static final int HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
    15	
    16	    private static final int HIGH_ENCHANTMENT_LEVEL = 5;
    17	
    18	    private ItemRiskSurcharges() {
    19	    }
    20	
    21	    /**
    22	     * Every item-specific risk surcharge the MHPCO charges, summed. This is the
    23	     * one place that says which risks are item-specific: a new item risk is
    24	     * added here and nowhere else.
    25	     */
    26	    public static BigDecimal totalItemSurcharges(List<Item> items) {
    27	        return curseSurcharge(items).add(highEnchantmentSurcharge(items));
    28	    }
    29	
    30	    /**
    31	     * Cursed items add a 50 % risk surcharge on their own base premium.
    32	     */
    33	    private static BigDecimal curseSurcharge(List<Item> items) {
    34	        return surchargeOnItemsAtRisk(items, Item::cursed, CURSE_SURCHARGE_PERCENT);
    35	    }
    36	
    37	    /**
    38	     * Highly enchanted items -- enchantment level 5 or more -- add a 30 % risk
    39	     * surcharge on their own base premium.
    40	     */
    41	    private static BigDecimal highEnchantmentSurcharge(List<Item> items) {
    42	        return surchargeOnItemsAtRisk(
    43	                items, ItemRiskSurcharges::isHighlyEnchanted, HIGH_ENCHANTMENT_SURCHARGE_PERCENT);
    44	    }
    45	
    46	    private static boolean isHighlyEnchanted(Item item) {
    47	        return item.enchantment() >= HIGH_ENCHANTMENT_LEVEL;
    48	    }
    49	
    50	    /**
    51	     * The MHPCO's scope rule for every item-specific surcharge, decided in one
    52	     * place: only the items carrying the risk are charged, each against its own
    53	     * base premium, and the amounts are summed into the policy premium.
    54	     *
    55	     * Every risk the MHPCO recognises is a property of a main item -- a curse
    56	     * or an enchantment -- so only main items can carry one, and the base
    57	     * premium measured against is the price-list premium of that main item.
    58	     */
    59	    private static BigDecimal surchargeOnItemsAtRisk(
    60	            List<Item> items, Predicate<Item> carriesTheRisk, int surchargePercent) {
    61	        return items.stream()
    62	                .filter(carriesTheRisk)
    63	                .map(item -> Percentage.of(MainItemPricing.mainItemBasePremium(item), surchargePercent))
    64	                .reduce(BigDecimal.ZERO, BigDecimal::add);
    65	    }
    66	}
